fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let ax: i32 = w / 4;
    let bx: i32 = w * 3 / 4;
    let cy: i32 = h / 2;
    host::display::clear(0x060608);
    let mut i: i32 = 0;
    while i < 32 {
        let a1: i32 = (i + t / 10) & 31;
        let a2: i32 = (i - t / 10) & 31;
        let ex1: i32 = ax + tab[(a1 + 8) & 31] * 700 / 127;
        let ey1: i32 = cy + tab[a1] * 700 / 127;
        let ex2: i32 = bx + tab[(a2 + 8) & 31] * 700 / 127;
        let ey2: i32 = cy + tab[a2] * 700 / 127;
        host::display::draw_line(ax, cy, ex1, ey1, 0x4aa8ff);
        host::display::draw_line(bx, cy, ex2, ey2, 0xff6a4a);
        i = i + 1;
    }
    host::display::fill_rect(ax - 3, cy - 3, 6, 6, 0xffffff);
    host::display::fill_rect(bx - 3, cy - 3, 6, 6, 0xffffff);
    host::display::present();
}
